<style>
/* Scoped shell styles: no dependency on a new Tailwind compilation. */
.cn-shell{background:#f5f7fb;color:#17243a;min-height:100vh}.cn-shell *{box-sizing:border-box}
.cn-sidebar{background:#10243a;color:#d4e0ed;padding:28px 18px;position:fixed;inset:0 auto 0 0;width:244px;overflow-y:auto;z-index:40}
.cn-brand{display:flex;gap:12px;align-items:center;color:white;font-size:22px;font-weight:750;letter-spacing:-.5px;text-decoration:none}.cn-brand small{display:block;font-size:11px;font-weight:400;letter-spacing:0;color:#a9bdd1;margin-top:2px}.cn-brand-mark{display:grid;place-items:center;background:#51dbc5;color:#10243a;width:38px;height:38px;border-radius:12px}
.cn-context{margin:28px 0 20px;padding:16px 12px;background:#1b344c;border-radius:12px}.cn-context strong{display:block;font-size:14px;margin-top:6px;overflow-wrap:anywhere}.cn-eyebrow{font-size:10px;letter-spacing:1.3px;text-transform:uppercase;font-weight:700;color:#a9bdd1}
.cn-menu summary{display:none}.cn-nav-group{margin:24px 0}.cn-nav-group>p{margin:0 12px 9px}.cn-nav-group a{display:flex;align-items:center;justify-content:space-between;padding:11px 12px;border-radius:8px;font-size:13px;font-weight:600;text-decoration:none;margin:3px 0}.cn-nav-group a:hover{background:#213e57;color:white}.cn-nav-group a[aria-current]{background:#d5f8ef;color:#123c35}.cn-count{font-size:11px;background:#f8c76b;color:#39250a;padding:2px 7px;border-radius:20px}
.cn-account{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #345066;padding:20px 8px;font-size:12px;margin-top:28px}.cn-account button:hover,.cn-account a:hover{text-decoration:underline}
.cn-content{margin-left:244px;min-width:0}.cn-topline{padding:14px 32px;background:#fff;border-bottom:1px solid #e2e8f0;font-size:12px;color:#52657a;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.cn-topline strong{font-weight:600;color:#17243a}
.cn-subnav{display:flex;flex-wrap:wrap;gap:8px;padding:12px 32px;background:#fff;border-bottom:1px solid #e2e8f0;font-size:12px}.cn-subnav a{padding:7px 12px;border-radius:7px;border:1px solid #dce4ee}.cn-subnav a[aria-current]{background:#e8f2ff;border-color:#a4c4ee;color:#234e85}
.cn-skip{position:fixed;left:260px;top:-100px;background:white;color:#10243a;padding:12px;z-index:100}.cn-skip:focus{top:12px}
.cn-shell a:focus-visible,.cn-shell button:focus-visible,.cn-shell summary:focus-visible{outline:3px solid #0e9f91;outline-offset:3px}
.cn-panel{background:white;border:1px solid #dce4ee;border-radius:16px;padding:24px}.cn-panel h2{font-size:18px;font-weight:700}.cn-panel p{font-size:14px;line-height:1.6;color:#52657a;margin-top:6px}.cn-card-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cn-channel-card{padding:20px;border:1px solid #dce4ee;border-radius:12px;background:white;display:flex;flex-direction:column;align-items:flex-start}.cn-channel-card h3{font-size:15px;font-weight:700;margin:16px 0 0}.cn-channel-card p{font-size:13px;line-height:1.6;color:#52657a;margin:6px 0 18px}.cn-channel-card .cn-button{margin-top:auto}.cn-channel-mark{display:inline-grid;place-items:center;width:38px;height:38px;border-radius:10px;background:#e9f5f3;color:#126555;font-size:12px;font-weight:750}.cn-planned{font-size:11px;background:#f0f3f7;color:#52657a;border-radius:20px;padding:4px 9px;margin-top:auto}.cn-button{display:inline-flex;padding:10px 15px;border-radius:8px;background:#135e54;color:white!important;font-size:13px;font-weight:650;text-decoration:none}.cn-button:hover{background:#0d4b43}.cn-quicklinks{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.cn-muted-link{font-size:13px;color:#315b88;text-decoration:underline}.cn-work-area{max-width:1280px;margin:auto;padding:28px 32px}.cn-work-area>section{margin-bottom:20px}
@media(min-width:1024px){.cn-menu:not([open])>nav{display:block}}
@media(max-width:1100px){.cn-card-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:1023px){.cn-sidebar{position:relative;width:auto;padding:18px 20px}.cn-content{margin-left:0}.cn-context{margin:16px 0;padding:10px 12px}.cn-menu summary{display:list-item;cursor:pointer;padding:10px 0;font-size:13px;font-weight:600}.cn-nav-group{margin:16px 0}.cn-account{margin-top:12px;padding:16px 4px 0}.cn-topline,.cn-subnav{padding:12px 20px}.cn-skip{left:12px}.cn-work-area{padding:20px}.cn-brand{font-size:20px}}
@media(max-width:560px){.cn-card-grid{grid-template-columns:1fr}.cn-panel{padding:20px}.cn-topline{font-size:11px}}
@media(prefers-reduced-motion:reduce){.cn-shell *{scroll-behavior:auto!important;transition:none!important}}
</style>
